// 🔧 Préparer les données pour Playwright
// Cette fonction transforme les données Notion en config de test

const items = $input.all();
const testConfigs = [];

for (const item of items) {
  const config = {
    // ID de la page Notion pour mise à jour ultérieure
    notionPageId: item.json.id,

    // Configuration du test
    eventName: item.json['Événement'] || 'unnamed_event',
    url: item.json['URL Test'] || '',
    userAction: item.json['Action utilisateur'] || '',
    dataLayerEventName: item.json['Nom dataLayer'] || item.json['Événement'],
    expectedParams: item.json['Paramètres attendus'] || '{}',

    // Quels outils tester ?
    testGA4: item.json.GA4 === true,
    testAmplitude: item.json.Amplitude === true,
    testMixpanel: item.json.Mixpanel === true,

    // Métadonnées
    type: item.json.Type || 'Custom',
    priority: item.json['Priorité'] || '🟡 Moyenne',
    context: item.json['Page/Contexte'] || ''
  };

  // Valider que l'URL est présente
  if (!config.url) {
    config.skipTest = true;
    config.skipReason = 'URL manquante';
  }

  testConfigs.push({ json: config });
}

return testConfigs;

// 📊 Parser les résultats du test Playwright
// Cette fonction analyse le JSON retourné par Playwright

const items = $input.all();
const parsedResults = [];

for (const item of items) {
  try {
    // Le résultat de Playwright est dans stdout
    const playwrightOutput = item.json.stdout;

    // Extraire le JSON des résultats
    const jsonMatch = playwrightOutput.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      const results = JSON.parse(jsonMatch[0]);

      // Formater pour Notion
      const notionUpdate = {
        notionPageId: item.json.notionPageId,
        success: results.success,

        // Statut
        status: results.success ? '✅ Validé' : '❌ Échoué',

        // Date d'exécution
        executionDate: results.timestamp,

        // Détails d'erreur
        errorDetails: results.errors.join(', ') || '',

        // Résumé des outils détectés
        toolsSummary: Object.entries(results.toolsDetected)
          .filter(([tool, detected]) => detected)
          .map(([tool, _]) => tool.toUpperCase())
          .join(', '),

        // Paramètres validés
        validatedParams: results.validatedParams || {},

        // Nombre d'événements capturés
        dataLayerEventsCount: results.dataLayerEvents.length,
        networkRequestsCount: results.networkRequests.length
      };

      parsedResults.push({ json: notionUpdate });
    } else {
      // Erreur de parsing
      parsedResults.push({
        json: {
          notionPageId: item.json.notionPageId,
          success: false,
          status: '❌ Échoué',
          errorDetails: 'Impossible de parser les résultats Playwright',
          executionDate: new Date().toISOString()
        }
      });
    }
  } catch (error) {
    parsedResults.push({
      json: {
        notionPageId: item.json.notionPageId,
        success: false,
        status: '❌ Échoué',
        errorDetails: error.message,
        executionDate: new Date().toISOString()
      }
    });
  }
}

return parsedResults;

// 📧 Générer un rapport récapitulatif

const items = $input.all();
const totalTests = items.length;
const successCount = items.filter(i => i.json.success).length;
const failCount = totalTests - successCount;

const failedTests = items
  .filter(i => !i.json.success)
  .map(i => `• ${i.json.eventName || 'Test inconnu'} : ${i.json.errorDetails}`);

const report = {
  subject: `🎯 Rapport Tracking - ${successCount}/${totalTests} tests validés`,
  summary: `
📊 RAPPORT HEBDOMADAIRE DE TRACKING

✅ Tests réussis : ${successCount}
❌ Tests échoués : ${failCount}
📈 Taux de succès : ${Math.round((successCount/totalTests)*100)}%

${ failCount > 0 ? `⚠️ TESTS EN ÉCHEC :\n${failedTests.join('\n')}` : '🎉 Tous les tests sont passés avec succès !' }

🔗 Voir le plan de mesure : https://notion.so/...
  `,
  totalTests,
  successCount,
  failCount,
  successRate: Math.round((successCount/totalTests)*100)
};

return [{ json: report }];
